// Shared data for the course shell: lessons, exercises, and progress parsed from PROGRESS.md.

const lessonFiles = import.meta.glob("/lessons/*.md", { query: "?raw", import: "default", eager: true });
const exerciseFiles = Object.keys(import.meta.glob("/exercises/*/*.html"));

// challenges/<slug>/target.html + mine.html, generated by Claude on request
export const challenges = [...new Set(Object.keys(import.meta.glob("/challenges/*/*.html")).map((p) => p.split("/")[2]))].sort();
import progressMd from "/PROGRESS.md?raw";

// "| 05.1 | ... | done | ... |" -> { "05.1": "done" }
export const progress = Object.fromEntries(
  progressMd
    .split("\n")
    .map((line) => line.split("|").map((c) => c.trim()))
    .filter((cells) => /^\d{2}\.\d+$/.test(cells[1] ?? ""))
    .map((cells) => [cells[1], cells[3].toLowerCase()]),
);

export const lessons = Object.entries(lessonFiles)
  .map(([path, md]) => {
    const slug = path.match(/\/lessons\/(.+)\.md$/)[1];
    const num = slug.slice(0, 2);
    const title = md.match(/^#\s+(.+)$/m)?.[1] ?? slug;
    const exercises = exerciseFiles
      .filter((p) => p.startsWith(`/exercises/${num}-`))
      .sort()
      .map((p) => {
        const file = p.split("/").pop();
        const n = file.match(/^(\d+)/)?.[1] ?? "?";
        const id = `${num}.${n}`;
        return { id, path: p, name: file.replace(/^\d+-/, "").replace(".html", ""), status: progress[id] ?? "todo" };
      });
    return { slug, num, title, md, exercises };
  })
  .sort((a, b) => a.slug.localeCompare(b.slug));
